PREFIX ul: <https://ul.edu.lb/kr/scm#>
SELECT (COUNT(DISTINCT ?c) AS ?n)
WHERE { ?c a ul:Country }

PREFIX ul: <https://ul.edu.lb/kr/scm#>
SELECT (COUNT(DISTINCT ?c) AS ?n)
WHERE { ?t ul:importedBy ?c ; ul:hasTier <https://ul.edu.lb/kr/id/tier/Tier_3A_Logic_Processors> }

PREFIX ul: <https://ul.edu.lb/kr/scm#>
SELECT (SUM(?v) AS ?totalUsd)
WHERE { ?t ul:hasTier <https://ul.edu.lb/kr/id/tier/Tier_2_Wafers> ; ul:tradeValueUsd ?v }

PREFIX ul: <https://ul.edu.lb/kr/scm#>
SELECT ?tier
WHERE { <https://ul.edu.lb/kr/id/tier/Tier_2_Wafers> ul:feeds ?d . BIND(REPLACE(STR(?d), "^.*/", "") AS ?tier) }

PREFIX ul: <https://ul.edu.lb/kr/scm#>
SELECT (SUM(?v) AS ?totalUsd)
WHERE { ?t ul:exportedBy ?c ; ul:tradeValueUsd ?v . ?c ul:name ?n . FILTER(LCASE(STR(?n)) = "china") }
